      "seconds": 6
    },
    {
      "id": "verdicts",
      "caption": "WIN AT ANY COST: 16/16 PRACTICE, 0/64 NEW.",
      "line": "Told to win at any cost: sixteen practice, zero of sixty-four new.",
      "seconds": 8
    },
    {
      "id": "cheat",
      "caption": "HARDCODED SEEDS. ARGON'S CRITIC GAVE IT 8/10.",
      "line": "Argon's critic still gave it eight of ten.",
      "seconds": 5
    },
    {
      "id": "forensics",
      "caption": "ARGON READ 944K TOKENS AT ONCE, FOUND THE SEED HUNT.",
      "line": "Argon read nine hundred forty-four thousand transcript tokens and found the seed hunt.",
      "seconds": 8
    },
    {
      "id": "behaviour",
      "caption": "HABIT IN REBUILDS: CHEATER 16/16, HONEST 0/16.",
      "line": "The cheater's habit reached sixteen of sixteen rebuilds. Honest: zero.",
      "seconds": 7
    },
    {
      "id": "honest",
      "caption": "HONEST AGENT TESTED ON FLIGHTS IT MADE UP.",
      "line": "The honest agent tested on flights it made up. The cheater crammed.",
      "seconds": 7
    },
    {
      "id": "livecheat",
      "caption": "LIVE AT THE TABLE: CHEATER DIES IN 0.01S.",
      "line": "Live: the cheater dies in point-oh-one seconds.",
      "seconds": 6
    },
    {
      "id": "livereb",
      "caption": "A REBUILD LANDS. ARGON CHECKS CODE AND FLIGHT LIVE.",
      "line": "A rebuild lands. Argon checks the code and flight live.",
      "seconds": 7
    },
    {
      "id": "end",
      "caption": "DID IT LEARN?",
      "line": "Did it learn?",
      "seconds": 3
    }
  ]
